DO $$ DECLARE s jsonb; BEGIN
SELECT state INTO s FROM public.noble_house_sheets WHERE house_id='harcourt';
IF (SELECT version FROM public.noble_house_sheets WHERE house_id='harcourt')<>2 THEN RAISE EXCEPTION 'Unexpected version'; END IF;
IF jsonb_array_length(s->'domains')<>4 OR jsonb_array_length(s->'holdings')<>21 OR jsonb_array_length(s->'units')<>6 THEN RAISE EXCEPTION 'Wrong number of assets'; END IF;
IF (SELECT count(*) FROM public.noble_house_ledger WHERE house_id='harcourt' AND action='import')<>1 THEN RAISE EXCEPTION 'No audit entry'; END IF;
IF (s->'permanent'->>'lands')::int<>55 OR (s->'permanent'->>'defense')::int<>35 OR (s->'permanent'->>'power')::int<>50 OR (s->'permanent'->>'wealth')::int<>51 THEN RAISE EXCEPTION 'Resource totals changed'; END IF;
IF (SELECT COALESCE(sum((c->>'amount')::int),0) FROM jsonb_array_elements(s->'holdings') h CROSS JOIN LATERAL jsonb_array_elements(h->'costs') c WHERE c->>'resource'='lands')<>55 THEN RAISE EXCEPTION 'Land cost mismatch'; END IF;
IF (SELECT COALESCE(sum((c->>'amount')::int),0) FROM jsonb_array_elements(s->'holdings') h CROSS JOIN LATERAL jsonb_array_elements(h->'costs') c WHERE c->>'resource'='defense')<>35 THEN RAISE EXCEPTION 'Defense cost mismatch'; END IF;
IF (SELECT COALESCE(sum((c->>'amount')::int),0) FROM jsonb_array_elements(s->'holdings') h CROSS JOIN LATERAL jsonb_array_elements(h->'costs') c WHERE c->>'resource'='wealth')<>51 THEN RAISE EXCEPTION 'Wealth cost mismatch'; END IF;
IF (SELECT COALESCE(sum((c->>'amount')::int),0) FROM jsonb_array_elements(s->'units') h CROSS JOIN LATERAL jsonb_array_elements(h->'costs') c WHERE c->>'resource'='power')<>50 THEN RAISE EXCEPTION 'Power cost mismatch'; END IF;
END $$;
SELECT jsonb_build_object('house',house_id,'version',version,'castle',(SELECT castle FROM public.campaign_houses WHERE id='harcourt'),'holdings',jsonb_array_length(state->'holdings'),'domains',jsonb_array_length(state->'domains'),'units',jsonb_array_length(state->'units')) AS verified FROM public.noble_house_sheets WHERE house_id='harcourt';
COMMIT;